#[target_feature(enable = "sse2")]
fn test_x86_sse2_mm_sad_epu8_impl() -> Result<Verdict, String> {
    unsafe {
        let result = unpack__m128i_to_u8_array(_mm_sad_epu8(create__m128i_from_i32_array([1, 2, 3, 4]), create__m128i_from_i32_array([5, 6, 7, 8])));
        check_array_equality(&result, &[8, 0, 0, 0, 0, 0, 0, 0, 8, 0, 0, 0, 0, 0, 0, 0]).map_err(|e| crate::cpu::with_call(e, "_mm_sad_epu8(create__m128i_from_i32_array([1, 2, 3, 4]), create__m128i_from_i32_array([5, 6, 7, 8]))"))?;

        crate::cpu::fuzz(&mut || {
            let _ = _mm_sad_epu8(create_random__m128i(), create_random__m128i());
        });
        Ok(Verdict::Checked)
    }
}

